using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using UnityEngine;
using HarborValeGreybox.Driving;
using HarborValeGreybox.Launch;
using HarborValeGreybox.Workshop;
namespace HarborValeGreybox.Racing {
public sealed class InventoryPlayerProbe:MonoBehaviour {
 static string folder; readonly List<string> checks=new List<string>(); bool failed; double deadline;
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)] static void Prepare(){var args=Environment.GetCommandLineArgs();int i=Array.IndexOf(args,"--inventory-check-dir");folder=Debug.isDebugBuild&&i>=0&&i+1<args.Length?Path.GetFullPath(args[i+1]):null;if(folder!=null){Directory.CreateDirectory(folder);DocksideTrialDirector.SavePathOverrideForTests=folder+"/isolated-v9.json";}}
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)] static void Hook(){if(folder!=null){var go=new GameObject("Isolated inventory native verification");DontDestroyOnLoad(go);go.AddComponent<InventoryPlayerProbe>();}}
 void Check(bool yes,string text){checks.Add((yes?"PASS ":"FAIL ")+text);File.WriteAllLines(folder+"/results.txt",checks);if(!yes){failed=true;Application.Quit(1);throw new Exception(text);}}
 void OnEnable(){Application.logMessageReceived+=Log;}void OnDisable(){Application.logMessageReceived-=Log;}void Log(string text,string trace,LogType type){if(!failed&&(type==LogType.Error||type==LogType.Exception))Check(false,"Runtime error: "+text);}void Update(){if(deadline>0&&!failed&&Time.realtimeSinceStartupAsDouble>deadline)Check(false,"Native inventory timeout");}
 IEnumerator Wait(Func<bool> condition){while(!condition())yield return null;yield return new WaitForSecondsRealtime(.3f);}
 IEnumerator Capture(string name){yield return new WaitForSecondsRealtime(.4f);yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(folder+"/"+name+".png");yield return new WaitForSecondsRealtime(.5f);Check(new FileInfo(folder+"/"+name+".png").Length>50000,"Nonblank native render: "+name);}
 static TrialSession Finish(TrialDefinition d){var s=new TrialSession(d);s.Tick(4,Vector3.zero,Vector3.zero);s.Tick(90,Vector3.zero,Vector3.zero);foreach(var g in d.checkpoints)s.Tick(.02f,g.Position-g.Forward,g.Position+g.Forward);return s;}
 void Parts(ExpandedWorkshop shop,string id){foreach(var part in shop.Catalog.MissingPath(shop.Build,shop.Catalog.Find(id)))Check(shop.Install(part.id),"Actual paid supporting part: "+part.id);}
 IEnumerator Start(){deadline=Time.realtimeSinceStartupAsDouble+600;yield return Wait(()=>HarborValeLaunch.Instance!=null);HarborValeLaunch.Instance.Open(HarborValeLaunch.CityScene);yield return Wait(()=>RivalRaceDirector.Instance?.Ready==true&&PhysicalGarage.Instance?.Ready==true&&FindAnyObjectByType<ExpandedWorkshop>()?.Ready==true);var director=RivalRaceDirector.Instance;var store=director.Trial.Store;var garage=PhysicalGarage.Instance;var car=director.Trial.vehicle;var shop=FindAnyObjectByType<ExpandedWorkshop>();car.externalInput=true;car.commandedHandbrake=false;car.commandedPedal=0;car.commandedServiceBrake=1;Screen.SetResolution(1400,800,FullScreenMode.Windowed);yield return new WaitForSecondsRealtime(.5f);Screen.SetResolution(1280,720,FullScreenMode.Windowed);yield return new WaitForSecondsRealtime(.6f);
 for(int i=0;i<450;i++)store.Settle(Finish(director.Trial.Definition),out _);var owned=new Dictionary<string,string>();foreach(var spec in VehicleLineup.All){store.BuyVehicle(Guid.NewGuid().ToString("N"),spec.id,spec.price);owned[spec.id]=store.Profile.fleet.selectedId;}store.SelectVehicle(Guid.NewGuid().ToString("N"),owned["car_coda"]);director.ApplyVehicle();car.ResetAt(garage.Building.TransformPoint(new Vector3(0,.35f,-1)),garage.Building.rotation);yield return new WaitForSecondsRealtime(1);Check(shop.Open()&&shop.InventoryMode,"G opens owned-car and engine inventory board inside real garage");shop.OpenUpgradeMode();Parts(shop,"gearbox_3");Parts(shop,"brakes_2");Parts(shop,"tires_2");shop.Close();store.SelectVehicle(Guid.NewGuid().ToString("N"),owned["car_bastion"]);director.ApplyVehicle();yield return new WaitForSecondsRealtime(.6f);Check(shop.Open(),"Purchased V8 opens workshop");shop.OpenUpgradeMode();Parts(shop,"induction_small_1");Parts(shop,"cooling_1");shop.OpenInventoryMode();var ui=shop.InventoryView;string engine=FleetLedger.Find(store.Profile.fleet,owned["car_bastion"]).engineId;int count=store.Profile.fleet.engines.Count;ui.Focus(owned["car_bastion"]);ui.BeginDragEngine(engine,owned["car_bastion"]);Check(ui.DropOnCar(owned["car_coda"])&&ui.HasPendingDrop,"Car-to-car drag quotes compatible engine transfer");yield return Capture("Engine_Transfer_Confirmation");Check(ui.ConfirmMove()&&car.PowertrainCarId=="car_coda"&&car.EngineModelId=="car_bastion"&&car.Body.mass==1275,"Confirmed swap drives actual coupe chassis with tuned V8 calibration and mass");Check(car.GetComponentsInChildren<WheelCollider>().Length==4,"Swapped actor retains exactly four physics contacts");ui.BeginDragEngine(engine,owned["car_coda"]);Check(ui.DropInStorage()&&!store.HasEngine(owned["car_coda"]),"Drag to storage removes exact engine and leaves chassis owned");ui.BeginDragEngine(engine);Check(!ui.DropOnCar(store.Profile.prototypeCarId),"GUI rejects unsupported V8-to-Finch fitment");ui.Focus(owned["car_coda"]);yield return Capture("Garage_Engine_Inventory");
 if(Environment.GetCommandLineArgs().Contains("--inventory-interactive")){File.WriteAllText(folder+"/ready-for-drag.txt",engine);yield return Wait(()=>store.HasEngine(owned["car_coda"])&&store.ActiveEngineModelId=="car_bastion");Check(true,"Physical mouse drag from stored V8 to focused left car tile and confirmation commits correctly");}else{ui.BeginDragEngine(engine);Check(ui.DropOnCar(owned["car_coda"])&&ui.ConfirmMove(),"Stored-engine drag fits receiver");}
 Check(store.Profile.fleet.engines.Count==count,"GUI transfers preserve unique engine count");yield return Capture("Garage_Swapped_Coupe");shop.Close();Check(new RaceProgressStore(store.PathName,director.Trial.Definition).ActiveEngineModelId=="car_bastion","Actual native inventory reload retains swapped V8");yield return new WaitForSecondsRealtime(1.2f);Check(FindObjectsByType<GameObject>(FindObjectsSortMode.None).Count(g=>g.name.StartsWith("Parked owned car | "))==2,"Physical garage displays two other owned cars without duplicate driving rigs");var viewCamera=Camera.main;var chase=viewCamera.GetComponent<FinchChaseCamera>();chase.enabled=false;viewCamera.transform.position=garage.Building.TransformPoint(new Vector3(19,9,-21));viewCamera.transform.LookAt(garage.Building.TransformPoint(new Vector3(0,1.3f,0)));yield return Capture("Garage_Owned_Cars_Physical");chase.enabled=true;car.ResetAt(director.Trial.Definition.checkpoints[0].Position+Vector3.up*.35f,Quaternion.LookRotation(director.Trial.Definition.checkpoints[0].Forward));yield return new WaitForSecondsRealtime(.8f);Check(director.OpenPanel(),"Transplanted car enters rival menu");director.SelectedRival="club";director.Pinks=true;director.StakeConfirmed=true;Check(director.StartRace()&&director.Race.Contract.playerModelId=="car_coda"&&director.Race.Contract.playerBuild.engineModelId=="car_bastion","Pink contract freezes actual coupe frame and transplanted V8");int raceEngineCount=store.Profile.fleet.engines.Count;Check(director.BeforeLeave(),"Swapped-car pink forfeit settles atomically");Check(FleetLedger.Find(store.Profile.fleet,owned["car_coda"]).owner=="rival"&&EngineInventoryLedger.Find(store.Profile.fleet,engine).owner=="rival"&&store.Profile.fleet.engines.Count==raceEngineCount,"Pink loss transfers same unique fitted engine with car title");Check(store.Profile.fleet.engines.Any(e=>e.owner=="player"&&e.modelId=="car_coda"&&string.IsNullOrEmpty(e.installedCarId)),"Displaced stored engine remains player-owned after receiver title loss");director.ReturnToRoad();string saved=File.ReadAllText(store.PathName);HarborValeLaunch.Instance.Open(HarborValeLaunch.MenuScene);yield return Wait(()=>!HarborValeLaunch.Instance.Busy);ExpandedWorkshop.RequestedTestModel="car_tempest";HarborValeLaunch.Instance.Open(HarborValeLaunch.SportsScene);yield return Wait(()=>FindAnyObjectByType<ExpandedWorkshop>()?.Ready==true);shop=FindAnyObjectByType<ExpandedWorkshop>();car=shop.Car;Check(shop.IsTest&&car.PowertrainCarId=="car_tempest"&&ChassisTuning.CrankHp(car.Engine.definition)>1000&&car.Engine.definition.IsTurbo,"Free Tempest test runs actual Blender car with >1000HP factory twin turbo");Check(car.GetComponentsInChildren<WheelCollider>().Length==4&&Math.Abs(car.wheelBase-2.76f)<.001,"Tempest uses its own axle geometry with one physics rig");car.externalInput=true;car.commandedHandbrake=false;car.commandedServiceBrake=1;yield return new WaitForSecondsRealtime(.8f);Check(shop.Open(),"Tempest free workshop opens");Parts(shop,"na_1");Parts(shop,"cooling_1");yield return Capture("Tempest_Free_Tuning");shop.Close();var cam=Camera.main;var follow=cam.GetComponent<FinchChaseCamera>();if(follow!=null)follow.enabled=false;cam.transform.position=car.transform.position+car.transform.TransformDirection(new Vector3(4,2,5));cam.transform.LookAt(car.transform.position+Vector3.up*.7f);yield return Capture("Tempest_Blender_Model");var tap=Camera.main.gameObject.AddComponent<TurboNativeAudioTap>();tap.Begin();car.commandedServiceBrake=1;car.commandedPedal=1;yield return new WaitForSecondsRealtime(2.5f);car.commandedServiceBrake=0;yield return new WaitForSecondsRealtime(3);car.commandedPedal=0;yield return new WaitForSecondsRealtime(1);Check(tap.Finish(folder+"/Tempest_Native_Mix.wav")>10000,"Native 8-cylinder twin-turbo listener produces audible final mix");Destroy(tap);Check(File.ReadAllText(DocksideTrialDirector.SavePathOverrideForTests)==saved,"Free Tempest tune leaves paid fleet save byte-identical");Check(!failed,"Native inventory run has no runtime errors");Application.Quit(0);}
}
}
